module xu_shared_icb_sram64 #(
  parameter integer THROTTLE_PERIOD=7,
  parameter integer THROTTLE_RESET_PHASE=2,
  parameter [2:0] XU_EMA=3'b010,
  parameter [1:0] XU_EMAW=2'b00
)(
